                Route::Local => {
                    let dispatch_started = Instant::now();
                    let activity = app.activity_for(request, scope.clone(), request_id, "local");
                    let result = async {
                        let runtime = app.runtime.as_ref().context("no cell runtime")?;
                        let response = runtime
                            .fetch_cell(
                                scope.clone(),
                                name,
                                RuntimeFetch {
                                    url,
                                    method,
                                    body,
                                    headers,
                                    request_id,
