                        celld::js::RequestBody::Bytes(bytes) => {
                            celld::js::RequestBody::Bytes(bytes.clone())
                        }
                        celld::js::RequestBody::Stream(stream_id) => {
                            celld::js::RequestBody::Stream(*stream_id)
