                                    .to_str()
                                    .ok()
                                    .map(|value| (header.to_string(), value.to_string()))
                            })
                            .collect();
                        abort.disarm();
                        let mut response = response;
                        let parked = peer_tunnel::park_upgrade(hyper::upgrade::on(&mut response));
