    ($reason:literal; $pattern:pat = $($tokens:tt)*) => {{
        $crate::__celld_domain_select!(@ {
            mode=(biased $reason);
            ()
        } $pattern = $($tokens)*)
    }};
    ($($tokens:tt)*) => {
        compile_error!("select_biased! requires a non-empty reason string as its first token")
    };
}

